css:
#tongsci1-3-2-2-3-crash .cr-body { grid-template-columns: 1040px minmax(0, 1fr); }
.cr-stage { position: relative; border: 2px solid var(--ink); border-radius: 12px; overflow: hidden; background: #e4e6e8; }
.cr-stage canvas { touch-action: none; cursor: grab; user-select: none; -webkit-user-select: none; }
.cr-stage canvas.holding { cursor: grabbing; }
.cr-stage .now-chip { top: auto; bottom: 10px; }
.cr-panel { gap: 12px; }
.cr-out { margin: 0; font-size: 19px; line-height: 1.45; background: #fffbe6; border: 2px solid var(--accent); border-radius: 12px; padding: 8px 14px; min-height: 4.4em; flex: none; }
.cr-out b { color: var(--accent); }
.cr-facts { display: grid; grid-template-columns: auto 1fr; gap: 6px 12px; margin: 0; font-size: 18px; line-height: 1.4; flex: none; }
.cr-facts dt { font-weight: 800; color: var(--accent); white-space: nowrap; }
.cr-facts dd { margin: 0; }
section.ex.u-done .cr-facts { display: none; }

